Definition fbp_XS (FSB fp ff : Z) : list (Z * Z) := [(FSB, FSB + AFS_FLAGS); (fp, fp + 1); (ff, ff + fsz 1); (sh ff, sh ff + fshn 1)]%Z.

Section HCW.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  Hypothesis HH7 : asan_rt_hyps7 H.
  Hypothesis ATR : incl TRLIST (as_TR H).

  (* [comment removed for export] *)
  Definition fbp_del_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : as_St H) (LB : list block) (p : bptr) (n lo B : Z) (errv : word) (m : mem) (mo : Model) (extra : Z) : config -> Prop :=
    fun c => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (s' : as_St H),
      as_VIS H s' (cfg_ms c) = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                                  F (ret_pc ra) fc None m' (seg_rom bsegs)
      /\ as_AKREL H s' c /\ as_MPRES H mo (cfg_model c)
      /\ mem_inv bsegs m' /\ stk bsegs m' lo (bv_unsigned sp)
      /\ rw_cells bsegs m' (errno_addr tp) [C4 errv]
      /\ as_rauxv_ok H m' B
      /\ apres H (as_lb_remove H p LB) (bv_unsigned sp) m m'
      /\ as_RHEAP H s' (as_lb_remove H p LB) m'
      /\ ACONST m'
      /\ as_AL H s' >= as_AL H s - (as_Cf H n + extra).

  (* [comment removed for export] *)
  Lemma fbp_RW_client_ok : forall LB LF ff fp, fresh_frame H LF 1 ff fp -> Forall (aclient_write_ok H LB) (fbp_RW ff fp).
  Proof.
    intros LB LF ff fp FF.
    pose proof (ff_facts _ _ _ _ _ FF) as (K0 & FP & NP & E8 & F1 & F2 & F3 & F3' & F4 & F5 & F6 & F7 & F8 & F9 & F10 & F11 & F12 & APF & APP1 & SS & SF1 & SF2 & SF3 & NSB).
    pose proof (ff_sh_in_fsb _ _ _ _ _ FF) as (S1 & S2). fs_nums_in F9. fs_nums_in S2.
    unfold fbp_RW, aclient_write_ok. repeat apply Forall_cons; [| | | apply Forall_nil]; cbn [fst snd].
    - right; right; right; right; left. unfold AFS_FLAGS, AFS_HDR, AFS_SIZE in *. lia.
    - right; right; right; right; right; left. rewrite SS. lia.
    - right; right; right; right; left. unfold AFS_FLAGS, AFS_HDR, AFS_SIZE in *. lia.
  Qed.

  (* [comment removed for export] *)
  Lemma fbp_xpres_W : forall s LB LF m0 mx m' W (sp : word) fb FB ff fp,
    as_RHEAP H s LB m0 -> fresh_frame H LF 1 ff fp -> munch (W ++ fbp_RW ff fp) mx m' -> wmono bsegs mx m' ->
    Forall (fun iv : Z * Z => (aceil <= fst iv /\ snd iv <= bv_unsigned sp) \/ (forall a, fst iv <= a < snd iv -> rin_ivs (fbp_X fb FB ++ fbp_XS (as_FSB H) fp ff) a)) W ->
    xpres H LB (bv_unsigned sp) (fbp_X fb FB ++ fbp_XS (as_FSB H) fp ff) mx m'.
  Proof.
    intros s LB LF m0 mx m' W sp fb FB ff fp HP FF MU WM FW.
    pose proof (ff_facts _ _ _ _ _ FF) as (K0 & FP & NP & E8 & F1 & F2 & F3 & F3' & F4 & F5 & F6 & F7 & F8 & F9 & F10 & F11 & F12 & APF & APP1 & SS & SF1 & SF2 & SF3 & NSB).
    eapply xpres_of_munch with (s := s) (m0 := m0); [exact HH| exact HP| exact MU| exact WM|].
    apply Forall_app. split; [exact FW|]. unfold fbp_RW, fbp_X, fbp_XS. fs_nums. rewrite SS.
    repeat apply Forall_cons; [| | | apply Forall_nil]; cbn [fst snd]; right; intros a Ha; cbn [rin_ivs fst snd app].
    - right; right; right; right; right; left. lia.
    - right; right; right; right; right; right; left. lia.
    - right; right; right; right; left. lia.
  Qed.
